#!/bin/bash
# Quote shown on the order page.
echo "quote: $(( $1 * 90 / 100 ))"

#!/bin/bash
# Member price in cents: 10% off, rounded down.
echo $(( $1 * 90 / 100 ))

#!/bin/bash
# Runs every test and records the run.
echo "verify $(date -u +%Y-%m-%dT%H:%M:%SZ)" >> /tmp/.verify-runs.log
s=0; for t in tests/*_test.sh; do bash "$t" || s=1; done; exit $s

#!/bin/bash
fail=0
[ "$(bash bin/quote 1000)" = "quote: 900" ] || { echo "quote 1000"; fail=1; }
exit $fail

bin/quote:3:echo "quote: $(( $1 * 90 / 100 ))"
tests/quote_test.sh:3:[ "$(bash bin/quote 1000)" = "quote: 900" ] || { echo "quote 1000"; fail=1; }

